"""Lab checks for the workshop sign-up desk. Do not edit this file.

Each test is named after the README task it checks; most failure messages name the next action.
Run every check from the lab folder:  python -m pytest -q
"""

import ast
import importlib
import inspect
import logging
import os
import subprocess
import sys
import textwrap
from pathlib import Path

import pytest

LAB = Path(__file__).resolve().parent.parent
STARTER = LAB / "starter"
if str(STARTER) not in sys.path:
    sys.path.insert(0, str(STARTER))

from signups import records  # noqa: E402

ENV = dict(os.environ, PYTHONDONTWRITEBYTECODE="1")


def tree_of(func):
    return ast.parse(textwrap.dedent(inspect.getsource(func)))


def has(tree, node_type):
    return any(isinstance(node, node_type) for node in ast.walk(tree))


def parse_file(path):
    return ast.parse(path.read_bytes())


def run(args, timeout=60):
    return subprocess.run(
        [sys.executable, *args], cwd=STARTER, capture_output=True, text=True, timeout=timeout, env=ENV
    )


def test_task01_session_status_and_tables_needed_port_the_java_methods():
    assert records.session_status(10, 10) == "full", "Task 1: taken == capacity is 'full'"
    assert records.session_status(10, 12) == "full", "Task 1: taken > capacity is 'full'"
    assert records.session_status(10, 8) == "almost full", "Task 1: 2 seats left is 'almost full'"
    assert records.session_status(10, 9) == "almost full", "Task 1: 1 seat left is 'almost full'"
    assert records.session_status(10, 7) == "open", "Task 1: 3 seats left is 'open'"
    chain = [node for node in ast.walk(tree_of(records.session_status)) if isinstance(node, ast.If)]
    assert any(len(node.orelse) == 1 and isinstance(node.orelse[0], ast.If) for node in chain), (
        "Task 1: keep the Java else-if as an elif branch in session_status"
    )
    assert records.tables_needed(10, 4) == 3, "Task 1: 10 guests at tables of 4 need 3 tables"
    assert records.tables_needed(8, 4) == 2, "Task 1: 8 guests at tables of 4 need 2 tables"
    assert records.tables_needed(0, 4) == 0, "Task 1: no guests need no tables"
    assert has(tree_of(records.tables_needed), ast.While), "Task 1: port tablesNeeded with its while loop"


def test_task02_find_signup_returns_none_and_describe_tests_it_with_is_none():
    signups = [
        {"email": "a@example.com", "name": "A", "session": "data"},
        {"email": "b@example.com", "name": "B", "session": "general"},
        {"email": "b@example.com", "name": "B", "session": "testing"},
    ]
    assert records.find_signup(signups, "b@example.com") is signups[1], (
        "Task 2: return the first matching sign-up dict itself"
    )
    assert records.find_signup(signups, "z@example.com") is None, "Task 2: return None when no email matches"
    assert records.find_signup([], "a@example.com") is None, "Task 2: an empty list has no match"
    assert has(tree_of(records.find_signup), ast.For), "Task 2: find_signup loops over the sign-ups with for"
    assert records.describe(signups, "a@example.com") == "a@example.com is in data", (
        "Task 2: describe returns '<email> is in <session>' for a match"
    )
    assert records.describe(signups, "z@example.com") == "z@example.com is not signed up", (
        "Task 2: describe returns '<email> is not signed up' when find_signup returns None"
    )
    compares = [node for node in ast.walk(tree_of(records.describe)) if isinstance(node, ast.Compare)]
    none_tests = [
        node
        for node in compares
        if any(isinstance(c, ast.Constant) and c.value is None for c in [node.left, *node.comparators])
    ]
    assert none_tests and all(isinstance(op, (ast.Is, ast.IsNot)) for n in none_tests for op in n.ops), (
        "Task 2: test the find_signup result with `is None`, never `== None`"
    )


def test_task03_normalize_signup_has_a_default_session_and_type_hints():
    row = {"email": "  Ana.Ruiz@Example.com ", "name": " ana ruiz ", "session": ""}
    assert records.normalize_signup(row) == {
        "email": "ana.ruiz@example.com",
        "name": "Ana Ruiz",
        "session": "general",
    }, "Task 3: clean email and name; an empty session falls back to the default 'general'"
    assert records.normalize_signup(default_session="intro", row=row)["session"] == "intro", (
        "Task 3: a keyword default_session replaces the default"
    )
    kept = records.normalize_signup({"email": "b@example.com", "name": "b", "session": "data"}, default_session="intro")
    assert kept["session"] == "data", "Task 3: a row that has a session keeps it"
    assert row["email"] == "  Ana.Ruiz@Example.com ", "Task 3: return a new dict; do not change the row"
    signature = inspect.signature(records.normalize_signup)
    assert signature.parameters["default_session"].default == "general", (
        "Task 3: give default_session the default value 'general'"
    )
    missing = [name for name, p in signature.parameters.items() if p.annotation is inspect.Parameter.empty]
    assert not missing, f"Task 3: add type hints to the parameters {missing}"
    assert signature.return_annotation is not inspect.Signature.empty, "Task 3: add a return type hint"


def test_task04_report_line_takes_any_values_and_keyword_fields():
    line = records.report_line("data", "1 signed up", "3 seats left", status="open")
    assert line == "data: 1 signed up, 3 seats left (status=open)", f"Task 4: got {line!r}"
    assert records.report_line("testing", "3 signed up") == "testing: 3 signed up", (
        "Task 4: no keyword fields means no bracket part"
    )
    assert records.report_line("x", 1, 2, b=True, a=1) == "x: 1, 2 (b=True, a=1)", (
        "Task 4: values may be any type (turn each into text with str); keep the keyword fields in the order given"
    )
    kinds = {p.kind for p in inspect.signature(records.report_line).parameters.values()}
    assert inspect.Parameter.VAR_POSITIONAL in kinds and inspect.Parameter.VAR_KEYWORD in kinds, (
        "Task 4: use *values and **fields in the signature"
    )


def test_task05_counts_use_dict_get_and_items_unpacking():
    signups = [{"session": "testing"}, {"session": "general"}, {"session": "testing"}]
    assert records.count_by_session(signups) == {"testing": 2, "general": 1}, (
        "Task 5: a session seen for the first time starts at 0 (use dict.get)"
    )
    assert records.count_by_session([]) == {}, "Task 5: no sign-ups give an empty dict"
    calls = [node for node in ast.walk(tree_of(records.count_by_session)) if isinstance(node, ast.Call)]
    assert any(isinstance(c.func, ast.Attribute) and c.func.attr == "get" for c in calls), (
        "Task 5: count with counts.get(session, 0)"
    )
    capacity = {"general": 5, "testing": 2, "data": 4}
    assert records.open_sessions(capacity, {"testing": 2, "general": 5}) == ["data"], (
        "Task 5: only sessions with a free seat, in capacity order"
    )
    assert records.open_sessions(capacity, {}) == ["general", "testing", "data"], (
        "Task 5: a session missing from counts has every seat free"
    )
    loops = [
        node
        for node in ast.walk(tree_of(records.open_sessions))
        if isinstance(node, (ast.For, ast.comprehension))
        and isinstance(node.target, ast.Tuple)
        and isinstance(node.iter, ast.Call)
        and isinstance(node.iter.func, ast.Attribute)
        and node.iter.func.attr == "items"
    ]
    assert loops, "Task 5: loop over capacity.items() and unpack each pair, as in: for session, seats in ..."
    emails = ["a@example.com", "b@example.com"]
    assert records.cancel(emails, "a@example.com") is True and emails == ["b@example.com"], (
        "Task 5: cancel removes the email from the same list and returns True"
    )
    assert records.cancel(emails, "z@example.com") is False and emails == ["b@example.com"], (
        "Task 5: cancelling an absent email returns False and changes nothing"
    )


def test_task06_comprehensions():
    signups = [
        {"email": "a@example.com", "session": "data"},
        {"email": "b@example.com", "session": "general"},
        {"email": "a@example.com", "session": "general"},
    ]
    assert records.emails_for(signups, "general") == ["b@example.com", "a@example.com"], (
        "Task 6: emails_for keeps the emails of that session, in order"
    )
    tree = tree_of(records.emails_for)
    assert has(tree, ast.ListComp) and not has(tree, ast.For), (
        "Task 6: rewrite the emails_for loop as one list comprehension"
    )
    assert records.unique_emails(signups) == {"a@example.com", "b@example.com"}, (
        "Task 6: unique_emails returns each email once, as a set"
    )
    assert has(tree_of(records.unique_emails), ast.SetComp), "Task 6: build unique_emails with a set comprehension"
    assert records.seats_left_by_session({"general": 5, "data": 4}, {"general": 2}) == {"general": 3, "data": 4}, (
        "Task 6: seats left is capacity minus sign-ups, and a session missing from counts has every seat free"
    )
    assert has(tree_of(records.seats_left_by_session), ast.DictComp), (
        "Task 6: build seats_left_by_session with a dict comprehension"
    )


def test_task07_aliasing_bugs_are_fixed():
    records.add_to_waitlist("first@example.com")
    second = records.add_to_waitlist("second@example.com")
    assert second == ["second@example.com"], (
        "Task 7: each call without a waitlist must start a new list; replace the mutable default with None"
    )
    mine = ["z@example.com"]
    assert records.add_to_waitlist("c@example.com", mine) is mine and mine == ["z@example.com", "c@example.com"], (
        "Task 7: a waitlist that is passed in is appended to and returned"
    )
    empty = []
    assert records.add_to_waitlist("d@example.com", empty) is empty and empty == ["d@example.com"], (
        "Task 7: an empty waitlist that is passed in is used too; test `waitlist is None`, not `not waitlist`"
    )
    signup = {"email": "a@example.com"}
    updated = records.mark_checked_in(signup)
    assert updated == {"email": "a@example.com", "checked_in": True}, "Task 7: the copy carries checked_in True"
    assert "checked_in" not in signup and updated is not signup, (
        "Task 7: mark_checked_in must copy the dict, not change the caller's sign-up"
    )


def test_task08_parse_seats_raises_signuperror_and_logs(caplog):
    error_class = getattr(records, "SignupError", None)
    assert isinstance(error_class, type) and issubclass(error_class, Exception), (
        "Task 8: define class SignupError(Exception) in records.py"
    )
    logger = getattr(records, "logger", None)
    assert isinstance(logger, logging.Logger) and logger.name == "signups.records", (
        "Task 8: create the module logger with logging.getLogger(__name__)"
    )
    source = parse_file(STARTER / "signups" / "records.py")
    assert any(
        isinstance(n, ast.Import) and any(a.name == "logging" for a in n.names) for n in source.body
    ), "Task 8: import the standard-library logging module at the top of records.py (import logging)"
    caplog.set_level(logging.DEBUG, logger="signups.records")
    assert records.parse_seats(" 2 ") == 2, "Task 8: ' 2 ' is 2 seats"
    with pytest.raises(error_class, match="whole number"):
        records.parse_seats("two")
    with pytest.raises(error_class, match="at least 1"):
        records.parse_seats("0")
    mine = [r for r in caplog.records if r.name == "signups.records"]
    errors = [r for r in mine if r.levelno == logging.ERROR]
    assert len(errors) == 1 and errors[0].exc_info, (
        "Task 8: log the caught ValueError once with logger.exception (only for text that is not a number)"
    )
    assert len([r for r in mine if r.levelno == logging.DEBUG]) == 3, (
        "Task 8: the finally block logs one DEBUG line for every value checked"
    )
    tries = [node for node in ast.walk(tree_of(records.parse_seats)) if isinstance(node, ast.Try)]
    assert tries and tries[0].orelse and tries[0].finalbody, "Task 8: use try / except / else / finally"
    handlers = [h for t in tries for h in t.handlers]
    assert handlers and all(isinstance(h.type, ast.Name) and h.type.id == "ValueError" for h in handlers), (
        "Task 8: catch ValueError only, never a bare except"
    )


def test_task09_summary_script_runs_and_imports_safely(capsys):
    sys.modules.pop("signups.cli", None)
    try:
        importlib.import_module("signups.cli")
    except BaseException as err:  # the starter calls main at import time
        pytest.fail(
            f"Task 9: importing signups.cli must run nothing, but it raised {err!r}; import what cli.py uses "
            "(step 1) and put the call of main behind the __name__ guard (step 3)"
        )
    captured = capsys.readouterr()
    assert captured.out == "" and captured.err == "", "Task 9: importing signups.cli must not run main"
    general = run(["-m", "signups.cli", "general"], timeout=30)
    assert general.returncode == 0, f"Task 9: python -m signups.cli general must exit 0; stderr was {general.stderr!r}"
    assert general.stdout == "general: 3 signed up, 2 seats left (status=almost full)\n", (
        f"Task 9: wrong summary line {general.stdout!r}"
    )
    testing = run(["-m", "signups.cli", "testing"], timeout=30)
    assert testing.stdout == "testing: 3 signed up, 0 seats left (status=full)\n", (
        f"Task 9: wrong summary line {testing.stdout!r}"
    )
    missing = run(["-m", "signups.cli"], timeout=30)
    assert missing.returncode == 2 and missing.stdout == "" and "usage" in missing.stderr, (
        "Task 9: with no session argument, print a usage line to stderr and exit with status 2"
    )
    unknown = run(["-m", "signups.cli", "cooking"], timeout=30)
    assert unknown.returncode == 1 and unknown.stderr == "unknown session: cooking\n", (
        "Task 9: an unknown session prints 'unknown session: <name>' to stderr and exits with status 1"
    )
    source = parse_file(STARTER / "signups" / "cli.py")
    assert any(isinstance(n, ast.Import) and any(a.name == "sys" for a in n.names) for n in source.body), (
        "Task 9: import the standard-library sys module at the top of cli.py (import sys)"
    )
    own = [
        n
        for n in source.body
        if isinstance(n, ast.ImportFrom)
        and (
            (n.level == 0 and n.module == "signups.records")
            or (n.level == 1 and n.module == "records")
            or (n.level == 0 and n.module == "signups" and any(a.name == "records" for a in n.names))
        )
    ]
    assert own, "Task 9: import from your own module with from signups.records import ..."
    params = list(inspect.signature(records.session_status).parameters)
    keyword_calls = [
        [k.arg for k in c.keywords]
        for c in ast.walk(source)
        if isinstance(c, ast.Call) and ast.unparse(c.func).endswith("session_status") and len(c.keywords) >= 2
    ]
    assert any(set(kw) == set(params) and kw != params for kw in keyword_calls), (
        "Task 9: call session_status with keyword arguments in the opposite order to its parameters "
        "(taken=..., capacity=...)"
    )
    calls = [n for n in ast.walk(source) if isinstance(n, ast.Call)]
    assert any(
        any(isinstance(a, ast.Starred) for a in c.args) and any(k.arg is None for k in c.keywords) for c in calls
    ), "Task 9: call report_line with a list unpacked by * and a dict unpacked by **"


MUTANTS = {
    "session_status always returns 'open'": "r.session_status = lambda capacity, taken: 'open'",
    "session_status never returns 'almost full'": (
        "r.session_status = lambda capacity, taken: 'full' if taken >= capacity else 'open'"
    ),
    "parse_seats returns 0 instead of raising": "r.parse_seats = lambda text: 0",
    "parse_seats raises ValueError instead of SignupError": "r.parse_seats = lambda text: int(text)",
}


def run_learner_tests(patch=""):
    code = (
        "import sys, pytest\n"
        "import signups.records as r\n"
        f"{patch}\n"
        "sys.exit(pytest.main(['-q', '-p', 'no:cacheprovider', 'test_signups.py']))\n"
    )
    return run(["-c", code])


def decorator_names(func):
    names = []
    for dec in func.decorator_list:
        target = dec.func if isinstance(dec, ast.Call) else dec
        names.append(ast.unparse(target))
    return names


def all_functions(tree):
    found = [n for n in tree.body if isinstance(n, ast.FunctionDef)]
    for cls in (n for n in tree.body if isinstance(n, ast.ClassDef)):
        found += [n for n in cls.body if isinstance(n, ast.FunctionDef)]
    return found


def case_count(tree, dec):
    values = dec.args[1] if len(dec.args) >= 2 else next((k.value for k in dec.keywords if k.arg == "argvalues"), None)
    if isinstance(values, ast.Name):
        for node in tree.body:
            if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == values.id for t in node.targets):
                values = node.value
    return len(values.elts) if isinstance(values, (ast.List, ast.Tuple)) else 0


def test_task10_your_tests_use_fixtures_parametrize_and_raises_and_catch_bugs():
    tree = parse_file(STARTER / "test_signups.py")
    functions = all_functions(tree)
    fixtures = [f.name for f in functions if {"pytest.fixture", "fixture"} & set(decorator_names(f))]
    tests = [f for f in functions if f.name.startswith("test_")]
    assert fixtures and any(a.arg in fixtures for t in tests for a in t.args.args), (
        "Task 10: write a @pytest.fixture and use it as a parameter of a test"
    )
    parametrized = [
        (t, case_count(tree, dec))
        for t in tests
        for dec in t.decorator_list
        if isinstance(dec, ast.Call) and ast.unparse(dec.func).endswith("mark.parametrize")
    ]
    assert any(cases >= 3 for _, cases in parametrized), "Task 10: parametrize one test with at least 3 cases"
    assert any(cases >= 3 and any(a.arg in fixtures for a in t.args.args) for t, cases in parametrized), (
        "Task 10: the parametrized test also takes your fixture (room) as a parameter"
    )
    assert any(
        isinstance(n, ast.With) and any(ast.unparse(i.context_expr).startswith(("pytest.raises(", "raises(")) for i in n.items)
        for n in ast.walk(tree)
    ), "Task 10: check the SignupError case with `with pytest.raises(SignupError):`"
    clean = run_learner_tests()
    assert clean.returncode == 0, "Task 10: your tests must pass against your code:\n" + clean.stdout[-1500:]
    for bug, patch in MUTANTS.items():
        result = run_learner_tests(patch)
        assert result.returncode != 0, f"Task 10: your tests still pass when {bug}; add a test that catches it"
